void SAL_CALL PropertyControlExtender::disposing( const EventObject& Source )
    {
        OSL_ENSURE( Source.Source == mxControlWindow, "PropertyControlExtender::disposing: where does this come from?" );
        (void)Source.Source;
        mxControlWindow.clear();
        mxControl.clear();
    }
